import React, { useState } from 'react';
import { fetchCurrentWeather, fetchForecast, WeatherData, ForecastDay } from './api/weather';

const API_KEY = import.meta.env.VITE_OPENWEATHER_API_KEY || '';

interface WeatherState {
  current: WeatherData | null;
  forecast: ForecastDay[];
  loading: boolean;
  error: string | null;
}

function WeatherIcon({ icon, size = 48 }: { icon: string; size?: number }) {
  return (
    <img
      src={`https://openweathermap.org/img/wn/${icon}@2x.png`}
      alt="weather icon"
      width={size}
      height={size}
      className="inline-block"
    />
  );
}

function CurrentWeather({ data }: { data: WeatherData }) {
  return (
    <div className="bg-gradient-to-br from-blue-500 to-blue-700 rounded-2xl p-8 text-white shadow-xl">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-semibold">{data.city}</h2>
          <p className="text-blue-100 capitalize mt-1">{data.description}</p>
        </div>
        <WeatherIcon icon={data.icon} size={80} />
      </div>
      <div className="mt-6">
        <span className="text-6xl font-bold">{data.temperature}°</span>
        <span className="text-blue-200 ml-2">Feels like {data.feelsLike}°</span>
      </div>
      <div className="grid grid-cols-3 gap-4 mt-6 pt-4 border-t border-blue-400/30">
        <div>
          <p className="text-blue-200 text-sm">Humidity</p>
          <p className="text-lg font-medium">{data.humidity}%</p>
        </div>
        <div>
          <p className="text-blue-200 text-sm">Wind</p>
          <p className="text-lg font-medium">{data.windSpeed} m/s</p>
        </div>
        <div>
          <p className="text-blue-200 text-sm">Pressure</p>
          <p className="text-lg font-medium">{data.pressure} hPa</p>
        </div>
      </div>
    </div>
  );
}

function ForecastCard({ day }: { day: ForecastDay }) {
  const dateObj = new Date(day.date);
  const weekday = dateObj.toLocaleDateString('en-US', { weekday: 'short' });

  return (
    <div className="bg-white/10 backdrop-blur rounded-xl p-4 text-center hover:bg-white/20 transition">
      <p className="text-sm font-medium text-gray-300">{weekday}</p>
      <WeatherIcon icon={day.icon} size={40} />
      <div className="mt-2">
        <span className="text-white font-semibold">{day.tempHigh}°</span>
        <span className="text-gray-400 ml-1">{day.tempLow}°</span>
      </div>
      <p className="text-xs text-gray-400 mt-1">{day.precipitation.toFixed(0)}% rain</p>
    </div>
  );
}

export default function App() {
  const [city, setCity] = useState('London');
  const [weather, setWeather] = useState<WeatherState>({
    current: null,
    forecast: [],
    loading: false,
    error: null,
  });

  const handleSearch = async () => {
    setWeather(prev => ({ ...prev, loading: true, error: null }));

    const [current, forecast] = await Promise.all([
      fetchCurrentWeather(city, API_KEY),
      fetchForecast(city, API_KEY),
    ]);

    setWeather({ current, forecast, loading: false, error: null });
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      <div className="max-w-2xl mx-auto px-4 py-12">
        <h1 className="text-3xl font-bold mb-8">Weather Dashboard</h1>

        <div className="flex gap-3 mb-8">
          <input
            type="text"
            value={city}
            onChange={e => setCity(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSearch()}
            placeholder="Enter city name..."
            className="flex-1 bg-gray-800 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <button
            onClick={handleSearch}
            disabled={weather.loading}
            className="bg-blue-600 hover:bg-blue-700 px-6 py-3 rounded-lg font-medium transition disabled:opacity-50"
          >
            {weather.loading ? 'Loading...' : 'Search'}
          </button>
        </div>

        {weather.error && (
          <div className="bg-red-500/20 border border-red-500/50 rounded-lg p-4 mb-6 text-red-300">
            {weather.error}
          </div>
        )}

        {weather.current && <CurrentWeather data={weather.current} />}

        {weather.forecast.length > 0 && (
          <div className="mt-8">
            <h3 className="text-lg font-semibold mb-4">5-Day Forecast</h3>
            <div className="grid grid-cols-5 gap-3">
              {weather.forecast.map(day => (
                <ForecastCard key={day.date} day={day} />
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

