      setWeather({ current, forecast, loading: false, error: null });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to fetch weather data';
      setWeather(prev => ({ ...prev, loading: false, error: message }));
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      <div className="max-w-2xl mx-auto px-4 py-12">
        <h1 className="text-3xl font-bold mb-8">Weather Dashboard</h1>

        <div className="flex gap-3 mb-8">
          <input
            type="text"
            value={city}
            onChange={e => setCity(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSearch()}
            placeholder="Enter city name..."
            className="flex-1 bg-gray-800 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <button
            onClick={handleSearch}
            disabled={weather.loading}
            className="bg-blue-600 hover:bg-blue-700 px-6 py-3 rounded-lg font-medium transition disabled:opacity-50"
          >
            {weather.loading ? 'Loading...' : 'Search'}
          </button>
        </div>

        {weather.error && (
          <div className="bg-red-500/20 border border-red-500/50 rounded-lg p-4 mb-6 text-red-300">
            {weather.error}
          </div>
        )}

        {weather.loading && (
          <div className="animate-pulse">
            <div className="bg-gray-800 rounded-2xl p-8">
              <div className="flex items-center justify-between">
                <div>
                  <div className="h-7 w-32 bg-gray-700 rounded" />
                  <div className="h-4 w-48 bg-gray-700 rounded mt-3" />
                </div>
                <div className="h-16 w-16 bg-gray-700 rounded-full" />
              </div>
              <div className="h-14 w-24 bg-gray-700 rounded mt-6" />
              <div className="grid grid-cols-3 gap-4 mt-6 pt-4 border-t border-gray-700">
                <div className="h-12 bg-gray-700 rounded" />
                <div className="h-12 bg-gray-700 rounded" />
                <div className="h-12 bg-gray-700 rounded" />
              </div>
            </div>
            <div className="grid grid-cols-5 gap-3 mt-8">
              {[...Array(5)].map((_, i) => (
                <div key={i} className="h-28 bg-gray-800 rounded-xl" />
              ))}
            </div>
          </div>
        )}

        {!weather.loading && weather.current && <CurrentWeather data={weather.current} />}

        {weather.forecast.length > 0 && (
          <div className="mt-8">
            <h3 className="text-lg font-semibold mb-4">5-Day Forecast</h3>
            <div className="grid grid-cols-5 gap-3">
              {weather.forecast.map(day => (
                <ForecastCard key={day.date} day={day} />
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

const API_BASE = 'https://api.openweathermap.org/data/2.5';

export interface WeatherData {
  city: string;
  temperature: number;
  feelsLike: number;
  humidity: number;
  description: string;
  icon: string;
  windSpeed: number;
  pressure: number;
}

export interface ForecastDay {
  date: string;
  tempHigh: number;
  tempLow: number;
  description: string;
  icon: string;
  precipitation: number;
}

export async function fetchCurrentWeather(
  city: string,
  apiKey: string
): Promise<WeatherData> {
  const url = `${API_BASE}/weather?q=${encodeURIComponent(city)}&appid=${apiKey}&units=metric`;
  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Weather API error: ${response.status} ${response.statusText}`);
  }

  const data = await response.json();

  return {
    city: data.name,
    temperature: Math.round(data.main.temp),
    feelsLike: Math.round(data.main.feels_like),
    humidity: data.main.humidity,
    description: data.weather[0].description,
    icon: data.weather[0].icon,
    windSpeed: data.wind.speed,
    pressure: data.main.pressure,
  };
}

export async function fetchForecast(
  city: string,
  apiKey: string
): Promise<ForecastDay[]> {
  const url = `${API_BASE}/forecast/daily?q=${encodeURIComponent(city)}&appid=${apiKey}&units=metric&cnt=5`;
  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Forecast API error: ${response.status} ${response.statusText}`);
  }

  const data = await response.json();

  const dailyMap = new Map<string, ForecastDay>();

  for (const entry of data.list) {
    const date = entry.dt_txt.split(' ')[0];
    const existing = dailyMap.get(date);

    if (!existing) {
      dailyMap.set(date, {
        date,
        tempHigh: Math.round(entry.main.temp_max),
        tempLow: Math.round(entry.main.temp_min),
        description: entry.weather[0].description,
        icon: entry.weather[0].icon,
        precipitation: entry.pop * 100,
      });
    } else {
      existing.tempHigh = Math.max(existing.tempHigh, Math.round(entry.main.temp_max));
      existing.tempLow = Math.min(existing.tempLow, Math.round(entry.main.temp_min));
    }
  }

  return Array.from(dailyMap.values()).slice(0, 5);
}

