import { describe, it, expect, vi, beforeEach } from 'vitest';
import { fetchCurrentWeather, fetchForecast } from './weather';

const mockWeatherResponse = {
  name: 'London',
  main: { temp: 18.5, feels_like: 17.2, humidity: 72, pressure: 1013 },
  weather: [{ description: 'scattered clouds', icon: '03d' }],
  wind: { speed: 4.1 },
};

const mockForecastResponse = {
  list: [
    {
      dt_txt: '2026-04-16 12:00:00',
      main: { temp_max: 20, temp_min: 12 },
      weather: [{ description: 'clear sky', icon: '01d' }],
      pop: 0.1,
    },
    {
      dt_txt: '2026-04-17 12:00:00',
      main: { temp_max: 22, temp_min: 14 },
      weather: [{ description: 'few clouds', icon: '02d' }],
      pop: 0.3,
    },
  ],
};

beforeEach(() => {
  vi.restoreAllMocks();
});

describe('fetchCurrentWeather', () => {
  it('should parse weather data correctly', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      json: () => Promise.resolve(mockWeatherResponse),
    });

    const result = await fetchCurrentWeather('London', 'test-key');

    expect(result.city).toBe('London');
    expect(result.temperature).toBe(19);
    expect(result.humidity).toBe(72);
    expect(result.description).toBe('scattered clouds');
  });

  it('should throw on API error', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 404,
      statusText: 'Not Found',
    });

    await expect(fetchCurrentWeather('InvalidCity', 'test-key'))
      .rejects.toThrow('Weather API error: 404 Not Found');
  });
});

describe('fetchForecast', () => {
  it('should parse and aggregate forecast data', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      json: () => Promise.resolve(mockForecastResponse),
    });

    const result = await fetchForecast('London', 'test-key');

    expect(result).toHaveLength(2);
    expect(result[0].date).toBe('2026-04-16');
    expect(result[0].tempHigh).toBe(20);
    expect(result[0].tempLow).toBe(12);
    expect(result[1].precipitation).toBe(30);
  });

  it('should limit to 5 days', async () => {
    const manyDays = {
      list: Array.from({ length: 8 }, (_, i) => ({
        dt_txt: `2026-04-${16 + i} 12:00:00`,
        main: { temp_max: 20 + i, temp_min: 10 + i },
        weather: [{ description: 'clear', icon: '01d' }],
        pop: 0.1,
      })),
    };

    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      json: () => Promise.resolve(manyDays),
    });

    const result = await fetchForecast('London', 'test-key');
    expect(result.length).toBeLessThanOrEqual(5);
  });
});

